import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { RoomService } from "modules/room/service/RoomService";
import { useEffect, useState } from "react";
import { ActivityIndicator, Image, Modal, StyleSheet } from "react-native";
import type { Asset } from "react-native-image-picker";
import Toast from "react-native-toast-message";
import { SingleSendItem } from "screens/room/fragments/single-send-item";
import {
  Button,
  GoBackHeader,
  Input,
  IpadScreenWrapper,
  Loading,
  RoomImage,
  ScreenLayout,
} from "shared/components";
import { useUploadPhoto } from "shared/hooks";
import { Colors, TextSize } from "shared/styles";
import { isIpad, offlineToastHelper } from "shared/utils";

export const EditRoom: React.FC<NativeStackScreenProps<Routes, "editRoom">> = ({
  route,
}) => {
  const { room } = route.params;
  const {
    isLoading,
    selectedAsset,
    isListOpen,
    handleChoosePhoto,
    handleTakePhoto,
    setIsListOpen,
    setSelectedAsset,
  } = useUploadPhoto();
  const [displayName, setDisplayName] = useState<string | undefined>(
    room?.displayName(),
  );
  const [topic, setTopic] = useState<string | undefined>(room?.topic());
  const [isSaving, setIsSaving] = useState(false);
  const [shouldRemoveAvatar, setShouldRemoveAvatar] = useState(false);
  const [isDirect, setIsDirect] = useState(false);
  const [userPowerLevel, setUserPowerLevel] = useState(0);
  const [nameLevel, setNameLevel] = useState(50);
  const [avatarLevel, setAvatarLevel] = useState(50);
  const [topicLevel, setTopicLevel] = useState(50);
  const canEditName = userPowerLevel >= nameLevel;
  const canEditAvatar = userPowerLevel >= avatarLevel;
  const canEditTopic = userPowerLevel >= topicLevel;

  const isRemoveDisabled = () => {
    if (isSaving || isDirect) return true;

    if (selectedAsset) return false;

    if (room.heroes()[0]?.avatarUrl || room.avatarUrl()) return false;

    return true;
  };

  useEffect(() => {
    room.isDirect().then(setIsDirect).catch(console.error);
    RoomService.getUserPowerLevel(room.id())
      .then((level) => setUserPowerLevel(level ?? 0))
      .catch(console.error);
    RoomService.getRoomPowerLevels(room.id())
      .then((pl) => {
        if (!pl) return;
        const vals = pl.values();
        setNameLevel(Number(vals.roomName));
        setAvatarLevel(Number(vals.roomAvatar));
        setTopicLevel(Number(vals.roomTopic));
      })
      .catch(console.error);
  }, [room]);

  const handleRemove = () => {
    setSelectedAsset(null);
    setShouldRemoveAvatar(true);
  };

  const handleSave = async () => {
    try {
      setIsSaving(true);

      let avatarToUpload: Asset | null | undefined;

      if (shouldRemoveAvatar) {
        avatarToUpload = null; // User wants to remove avatar
      } else if (selectedAsset) avatarToUpload = selectedAsset;

      await RoomService.updateRoom(
        room.id(),
        displayName === room?.displayName() ? undefined : displayName, //if the displayName is the same as the room's displayName, don't update it
        topic === room?.topic() ? undefined : topic, //if the topic is the same as the room's topic, don't update it
        avatarToUpload,
      );

      Toast.show({
        type: "success",
        text1: "Room updated successfully",
      });
    } catch (error) {
      console.error("Failed to update room:", error);
      offlineToastHelper("Failed to update room. Please try again.");
    } finally {
      setIsSaving(false);
    }
  };

  const rightComponent = () => {
    const shouldShow =
      shouldRemoveAvatar ||
      selectedAsset ||
      displayName !== room?.displayName() ||
      topic !== room?.topic();

    if (!shouldShow) return null;

    return (
      <Button.Wrapper onPress={handleSave} disabled={isSaving}>
        <Text>{isSaving ? "Saving..." : "Save"}</Text>
      </Button.Wrapper>
    );
  };

  if (!room) return null;

  return (
    <ScreenLayout>
      {isSaving && <Loading text="Saving..." />}
      <GoBackHeader
        title="Edit Room Deatils"
        rightComp={rightComponent()}
        margins={{ marginBottom: 40 }}
      />
      <IpadScreenWrapper scrollable>
        <Block align="center">
          <Block margins={{ marginBottom: 8 }}>
            {isLoading ? (
              <Block width={120} height={120} align="center" justify="center">
                <ActivityIndicator />
              </Block>
            ) : selectedAsset?.uri ? (
              <Block
                width={120}
                height={120}
                align="center"
                justify="center"
                border={{ borderRadius: 999 }}
                overflow="hidden"
              >
                <Image
                  source={{ uri: selectedAsset.uri }}
                  width={120}
                  height={120}
                />
              </Block>
            ) : shouldRemoveAvatar ? (
              <Block
                width={120}
                height={120}
                border={{
                  borderRadius: 999,
                  borderWidth: 2,
                  borderColor: Colors.white20,
                }}
                background={Colors.white20}
                align="center"
                justify="center"
              >
                <Text
                  size={TextSize.large}
                  color="white"
                  textTransform="uppercase"
                >
                  {room.displayName()?.charAt(0)}
                </Text>
              </Block>
            ) : (
              <RoomImage
                borderRadius={999}
                room={room}
                width={120}
                height={120}
              />
            )}
          </Block>
          {!isDirect && canEditAvatar && (
            <Block
              flexDirection="row"
              align="center"
              gap={12}
              margins={{ marginBottom: 40 }}
            >
              <Button.Wrapper
                onPress={() => setIsListOpen(true)}
                disabled={isLoading || isSaving}
              >
                <Block
                  flexDirection="row"
                  align="center"
                  gap={12}
                  paddings={[16, 12]}
                >
                  <Image
                    source={require("assets/icons/upload-simple-large.png")}
                    width={16}
                    height={16}
                    style={styles.icon}
                    tintColor={Colors.primary}
                  />
                  <Text size={TextSize.small} color={Colors.primary}>
                    Upload
                  </Text>
                </Block>
              </Button.Wrapper>
              <Button.Wrapper
                onPress={handleRemove}
                disabled={isRemoveDisabled()}
              >
                <Block
                  flexDirection="row"
                  align="center"
                  gap={12}
                  paddings={[16, 12]}
                >
                  <Image
                    source={require("assets/icons/trash.png")}
                    width={16}
                    height={16}
                    style={styles.icon}
                  />
                  <Text size={TextSize.small}>Remove</Text>
                </Block>
              </Button.Wrapper>
            </Block>
          )}
        </Block>
        <Block gap={20}>
          <Block gap={8}>
            <Text
              size={TextSize.tiny}
              color={Colors.white50}
              paddings={[0, 16]}
            >
              Display name
            </Text>
            <Input
              placeholder="Display name"
              value={displayName}
              disabled={isDirect || !canEditName}
              onChangeText={(value) => setDisplayName(value)}
            />
          </Block>
          <Block gap={8}>
            <Text
              size={TextSize.tiny}
              color={Colors.white50}
              paddings={[0, 16]}
            >
              Topic
            </Text>
            <Input
              placeholder="Add a topic"
              value={topic}
              disabled={!canEditTopic}
              onChangeText={(value) => setTopic(value)}
            />
          </Block>
        </Block>
      </IpadScreenWrapper>
      <Modal
        visible={isListOpen}
        transparent={true}
        presentationStyle="overFullScreen"
        animationType="fade"
      >
        <Block
          width="100%"
          height="100%"
          justify={isIpad() ? "center" : "flex-end"}
          align="center"
          background={Colors.black70}
          paddings={[40, 20]}
        >
          {isLoading && <Loading />}
          <Block maxWidth={600} width="100%" gap={8}>
            <Block
              width="100%"
              background={Colors.blackMinus3}
              border={{ borderRadius: 14 }}
            >
              <SingleSendItem
                title="Chose photo"
                showSeparator
                onPress={handleChoosePhoto}
              />
              <SingleSendItem
                title="Take a photo"
                showSeparator
                onPress={handleTakePhoto}
              />
            </Block>
            <Block
              width="100%"
              background={Colors.blackMinus3}
              border={{ borderRadius: 14 }}
            >
              <SingleSendItem
                title="Cancel"
                onPress={() => setIsListOpen(false)}
              />
            </Block>
          </Block>
        </Block>
      </Modal>
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  icon: {
    width: 16,
    height: 16,
  },
});

import { Block, Text } from "@prototyp/skeletor";
import type { FC } from "react";
import { Image, Modal } from "react-native";
import type { Asset } from "react-native-image-picker";
import { SingleSendItem } from "screens/room/fragments/single-send-item";
import { Button, Loading } from "shared/components";
import { useUploadPhoto } from "shared/hooks/useUploadPhoto";
import { MAX_MODAL_WIDTH } from "shared/const/max-modal-width";
import { Colors } from "shared/styles";
import { isIpad } from "shared/utils";

interface UploadPhotoProps {
  onImageSelected: (image: Asset | null) => void;
}

export const UploadPhoto: FC<UploadPhotoProps> = ({ onImageSelected }) => {
  const {
    isLoading,
    isListOpen,
    selectedImage,
    setIsListOpen,
    handleTakePhoto,
    handleChoosePhoto,
    handleRemovePhoto,
  } = useUploadPhoto(onImageSelected);

  return (
    <Block gap={16}>
      <Button.Wrapper onPress={() => setIsListOpen(true)} disabled={isLoading}>
        <Block flexDirection="row" align="center" gap={16}>
          <Block
            width={60}
            height={60}
            border={{ borderRadius: 30 }}
            background={selectedImage ? "transparent" : Colors.white10}
            justify="center"
            align="center"
            overflow="hidden"
          >
            {selectedImage ? (
              <Image
                source={{ uri: selectedImage }}
                style={{
                  width: 60,
                  height: 60,
                  borderRadius: 30,
                }}
                resizeMode="cover"
              />
            ) : (
              <Image
                source={require("assets/icons/camera.png")}
                width={24}
                height={24}
              />
            )}
          </Block>
          <Text>
            {isLoading
              ? "Loading..."
              : selectedImage
                ? "Change Photo"
                : "Upload Photo"}
          </Text>
        </Block>
      </Button.Wrapper>
      <Modal
        visible={isListOpen}
        transparent={true}
        presentationStyle="overFullScreen"
        animationType="fade"
      >
        <Block
          width="100%"
          height="100%"
          justify={isIpad() ? "center" : "flex-end"}
          align="center"
          background={Colors.black70}
          paddings={[40, 20]}
        >
          {isLoading && <Loading />}
          <Block maxWidth={600} width="100%" gap={8}>
            <Block
              width="100%"
              background={Colors.blackMinus3}
              border={{ borderRadius: 14 }}
            >
              <SingleSendItem
                title="Chose photo"
                showSeparator
                onPress={handleChoosePhoto}
              />
              <SingleSendItem
                title="Take a photo"
                showSeparator
                onPress={handleTakePhoto}
              />
              {selectedImage && (
                <SingleSendItem
                  title="Remove photo"
                  textColor={Colors.error}
                  onPress={handleRemovePhoto}
                />
              )}
            </Block>
            <Block
              width="100%"
              background={Colors.blackMinus3}
              border={{ borderRadius: 14 }}
            >
              <SingleSendItem
                title="Cancel"
                onPress={() => setIsListOpen(false)}
              />
            </Block>
          </Block>
        </Block>
      </Modal>
    </Block>
  );
};

import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { useAtomValue, useSetAtom } from "jotai";
import { StorageAtoms } from "modules/storage/jotai/atoms";
import { TimelineAtoms } from "modules/timeline/jotai/atoms";
import { UserService } from "modules/user/service/UserService";
import { useState } from "react";
import { ActivityIndicator, Image, Modal, StyleSheet } from "react-native";
import type { Asset } from "react-native-image-picker";
import Toast from "react-native-toast-message";
import { SingleSendItem } from "screens/room/fragments/single-send-item";
import {
  Button,
  GoBackHeader,
  Input,
  IpadScreenWrapper,
  Loading,
  ScreenLayout,
  UserImage,
} from "shared/components";
import { MAX_MODAL_WIDTH } from "shared/const/max-modal-width";
import { useUploadPhoto } from "shared/hooks";
import { Colors, TextSize } from "shared/styles";
import { isIpad, offlineToastHelper } from "shared/utils";

export const UserProfile: React.FC<
  NativeStackScreenProps<Routes, "userProfile">
> = () => {
  const user = useAtomValue(StorageAtoms.cachedProfile);
  const [userImageUri, setUserImageUri] = useState<string | undefined>(
    user?.avatarUrl,
  );
  const {
    isLoading,
    selectedAsset,
    isListOpen,
    setSelectedAsset,
    setIsListOpen,
    handleChoosePhoto,
    handleTakePhoto,
  } = useUploadPhoto();
  const [displayName, setDisplayName] = useState<string | undefined>(
    user?.displayName,
  );
  const [isSaving, setIsSaving] = useState(false);
  const [shouldRemoveAvatar, setShouldRemoveAvatar] = useState(false);
  const setImageViewerPayload = useSetAtom(TimelineAtoms.imageViewerPayload);

  const handleRemove = () => {
    setUserImageUri(undefined);
    setSelectedAsset(null);
    setShouldRemoveAvatar(true);
  };

  const handleSave = async () => {
    try {
      setIsSaving(true);

      let avatarToUpload: Asset | null | undefined;

      if (shouldRemoveAvatar) {
        avatarToUpload = null; // User wants to remove avatar
      } else if (selectedAsset) avatarToUpload = selectedAsset;

      const updated = await UserService.updateProfile(
        displayName,
        avatarToUpload,
      );

      setShouldRemoveAvatar(false);
      setSelectedAsset(null);

      // The user state will be automatically updated via the atom
      setUserImageUri(updated?.avatarUrl);
      setDisplayName(updated?.displayName);

      Toast.show({
        type: "success",
        text1: "Profile updated successfully",
      });
    } catch (error) {
      console.error("Failed to update profile:", error);
      offlineToastHelper("Failed to update profile. Please try again.");
    } finally {
      setIsSaving(false);
    }
  };

  const rightComponent = () => {
    const shouldShow =
      shouldRemoveAvatar || selectedAsset || displayName !== user?.displayName;

    if (!shouldShow) return null;

    return (
      <Button.Wrapper onPress={handleSave} disabled={isSaving}>
        <Text>{isSaving ? "Saving..." : "Save"}</Text>
      </Button.Wrapper>
    );
  };

  return (
    <ScreenLayout paddings={{ paddingHorizontal: 16 }}>
      {isSaving && <Loading text="Saving..." />}
      <GoBackHeader
        margins={{ marginBottom: 40 }}
        title="Profile"
        rightComp={rightComponent()}
      />
      <IpadScreenWrapper>
        <Block align="center">
          <Block margins={{ marginBottom: 8 }}>
            {isLoading ? (
              <Block width={120} height={120} align="center" justify="center">
                <ActivityIndicator />
              </Block>
            ) : selectedAsset?.uri ? (
              <Button.Wrapper
                onPress={() =>
                  selectedAsset.uri &&
                  setImageViewerPayload({ uri: selectedAsset.uri })
                }
              >
                <Block
                  width={120}
                  height={120}
                  align="center"
                  justify="center"
                  border={{ borderRadius: 999 }}
                  overflow="hidden"
                >
                  <Image
                    source={{ uri: selectedAsset.uri }}
                    width={120}
                    height={120}
                  />
                </Block>
              </Button.Wrapper>
            ) : (
              <UserImage
                avatarUrl={userImageUri}
                displayName={user?.displayName}
                width={120}
                height={120}
                borderRadius={999}
                onPress={(uri) => setImageViewerPayload({ uri })}
              />
            )}
          </Block>
          <Block
            flexDirection="row"
            align="center"
            gap={12}
            margins={{ marginBottom: 40 }}
          >
            <Button.Wrapper
              onPress={() => setIsListOpen(true)}
              disabled={isLoading || isSaving}
            >
              <Block
                flexDirection="row"
                align="center"
                gap={12}
                paddings={[16, 12]}
              >
                <Image
                  source={require("assets/icons/upload-simple-large.png")}
                  width={16}
                  height={16}
                  tintColor={Colors.primary}
                  style={styles.icon}
                />
                <Text size={TextSize.small} color={Colors.primary}>
                  Upload
                </Text>
              </Block>
            </Button.Wrapper>
            <Button.Wrapper onPress={handleRemove} disabled={isSaving}>
              <Block
                flexDirection="row"
                align="center"
                gap={12}
                paddings={[16, 12]}
              >
                <Image
                  source={require("assets/icons/trash.png")}
                  width={16}
                  height={16}
                  style={styles.icon}
                />
                <Text size={TextSize.small}>Remove</Text>
              </Block>
            </Button.Wrapper>
          </Block>
        </Block>
        <Block>
          <Text margins={{ marginBottom: 20 }}>Contact info</Text>
          <Block gap={20}>
            <Block gap={8}>
              <Text
                size={TextSize.tiny}
                color={Colors.white50}
                paddings={[0, 16]}
              >
                Display name
              </Text>
              <Input
                placeholder="Display name"
                value={displayName}
                background={Colors.white5}
                onChangeText={(value) => setDisplayName(value)}
              />
              <Text
                size={TextSize.small}
                color={Colors.white50}
                paddings={[0, 16]}
              >
                This is what others will see whenever you’re signed in.
              </Text>
            </Block>
            <Block gap={8}>
              <Text
                size={TextSize.tiny}
                color={Colors.white50}
                paddings={[0, 16]}
              >
                Username
              </Text>
              <Block
                border={{
                  borderRadius: 40,
                }}
                paddings={[10, 16]}
                background={Colors.white5}
              >
                <Text
                  font="InstrumentSans-Regular"
                  size={TextSize.small}
                  color={Colors.white50}
                >
                  {user?.userId}
                </Text>
              </Block>
            </Block>
          </Block>
        </Block>
      </IpadScreenWrapper>
      <Modal
        visible={isListOpen}
        transparent={true}
        presentationStyle="overFullScreen"
        animationType="fade"
      >
        <Block
          width="100%"
          height="100%"
          justify={isIpad() ? "center" : "flex-end"}
          align="center"
          background={Colors.black70}
          paddings={[40, 20]}
        >
          {isLoading && <Loading />}
          <Block maxWidth={600} width="100%" gap={8}>
            <Block
              width="100%"
              background={Colors.blackMinus3}
              border={{ borderRadius: 14 }}
            >
              <SingleSendItem
                title="Chose photo"
                showSeparator
                onPress={handleChoosePhoto}
              />
              <SingleSendItem
                title="Take a photo"
                showSeparator
                onPress={handleTakePhoto}
              />
            </Block>
            <Block
              width="100%"
              background={Colors.blackMinus3}
              border={{ borderRadius: 14 }}
            >
              <SingleSendItem
                title="Cancel"
                onPress={() => setIsListOpen(false)}
              />
            </Block>
          </Block>
        </Block>
      </Modal>
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  icon: {
    width: 16,
    height: 16,
  },
  delete: {
    width: "100%",
    marginTop: 40,
  },
});

import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { RoomService } from "modules/room/service/RoomService";
import { useEffect, useState } from "react";
import { ActivityIndicator, Image, Modal, StyleSheet } from "react-native";
import type { Asset } from "react-native-image-picker";
import Toast from "react-native-toast-message";
import { SingleSendItem } from "screens/room/fragments/single-send-item";
import {
  Button,
  GoBackHeader,
  Input,
  IpadScreenWrapper,
  Loading,
  RoomImage,
  ScreenLayout,
} from "shared/components";
import { MAX_MODAL_WIDTH } from "shared/const/max-modal-width";
import { useUploadPhoto } from "shared/hooks";
import { Colors, TextSize } from "shared/styles";
import { isIpad, offlineToastHelper } from "shared/utils";

export const EditRoom: React.FC<NativeStackScreenProps<Routes, "editRoom">> = ({
  route,
}) => {
  const { room } = route.params;
  const {
    isLoading,
    selectedAsset,
    isListOpen,
    handleChoosePhoto,
    handleTakePhoto,
    setIsListOpen,
    setSelectedAsset,
  } = useUploadPhoto();
  const [displayName, setDisplayName] = useState<string | undefined>(
    room?.displayName(),
  );
  const [topic, setTopic] = useState<string | undefined>(room?.topic());
  const [isSaving, setIsSaving] = useState(false);
  const [shouldRemoveAvatar, setShouldRemoveAvatar] = useState(false);
  const [isDirect, setIsDirect] = useState(false);
  const [userPowerLevel, setUserPowerLevel] = useState(0);
  const [nameLevel, setNameLevel] = useState(50);
  const [avatarLevel, setAvatarLevel] = useState(50);
  const [topicLevel, setTopicLevel] = useState(50);
  const canEditName = userPowerLevel >= nameLevel;
  const canEditAvatar = userPowerLevel >= avatarLevel;
  const canEditTopic = userPowerLevel >= topicLevel;

  const isRemoveDisabled = () => {
    if (isSaving || isDirect) return true;

    if (selectedAsset) return false;

    if (room.heroes()[0]?.avatarUrl || room.avatarUrl()) return false;

    return true;
  };

  useEffect(() => {
    room.isDirect().then(setIsDirect).catch(console.error);
    RoomService.getUserPowerLevel(room.id())
      .then((level) => setUserPowerLevel(level ?? 0))
      .catch(console.error);
    RoomService.getRoomPowerLevels(room.id())
      .then((pl) => {
        if (!pl) return;
        const vals = pl.values();
        setNameLevel(Number(vals.roomName));
        setAvatarLevel(Number(vals.roomAvatar));
        setTopicLevel(Number(vals.roomTopic));
      })
      .catch(console.error);
  }, [room]);

  const handleRemove = () => {
    setSelectedAsset(null);
    setShouldRemoveAvatar(true);
  };

  const handleSave = async () => {
    try {
      setIsSaving(true);

      let avatarToUpload: Asset | null | undefined;

      if (shouldRemoveAvatar) {
        avatarToUpload = null; // User wants to remove avatar
      } else if (selectedAsset) avatarToUpload = selectedAsset;

      await RoomService.updateRoom(
        room.id(),
        displayName === room?.displayName() ? undefined : displayName, //if the displayName is the same as the room's displayName, don't update it
        topic === room?.topic() ? undefined : topic, //if the topic is the same as the room's topic, don't update it
        avatarToUpload,
      );

      Toast.show({
        type: "success",
        text1: "Room updated successfully",
      });
    } catch (error) {
      console.error("Failed to update room:", error);
      offlineToastHelper("Failed to update room. Please try again.");
    } finally {
      setIsSaving(false);
    }
  };

  const rightComponent = () => {
    const shouldShow =
      shouldRemoveAvatar ||
      selectedAsset ||
      displayName !== room?.displayName() ||
      topic !== room?.topic();

    if (!shouldShow) return null;

    return (
      <Button.Wrapper onPress={handleSave} disabled={isSaving}>
        <Text>{isSaving ? "Saving..." : "Save"}</Text>
      </Button.Wrapper>
    );
  };

  if (!room) return null;

  return (
    <ScreenLayout>
      {isSaving && <Loading text="Saving..." />}
      <GoBackHeader
        title="Edit Room Deatils"
        rightComp={rightComponent()}
        margins={{ marginBottom: 40 }}
      />
      <IpadScreenWrapper scrollable>
        <Block align="center">
          <Block margins={{ marginBottom: 8 }}>
            {isLoading ? (
              <Block width={120} height={120} align="center" justify="center">
                <ActivityIndicator />
              </Block>
            ) : selectedAsset?.uri ? (
              <Block
                width={120}
                height={120}
                align="center"
                justify="center"
                border={{ borderRadius: 999 }}
                overflow="hidden"
              >
                <Image
                  source={{ uri: selectedAsset.uri }}
                  width={120}
                  height={120}
                />
              </Block>
            ) : shouldRemoveAvatar ? (
              <Block
                width={120}
                height={120}
                border={{
                  borderRadius: 999,
                  borderWidth: 2,
                  borderColor: Colors.white20,
                }}
                background={Colors.white20}
                align="center"
                justify="center"
              >
                <Text
                  size={TextSize.large}
                  color="white"
                  textTransform="uppercase"
                >
                  {room.displayName()?.charAt(0)}
                </Text>
              </Block>
            ) : (
              <RoomImage
                borderRadius={999}
                room={room}
                width={120}
                height={120}
              />
            )}
          </Block>
          {!isDirect && canEditAvatar && (
            <Block
              flexDirection="row"
              align="center"
              gap={12}
              margins={{ marginBottom: 40 }}
            >
              <Button.Wrapper
                onPress={() => setIsListOpen(true)}
                disabled={isLoading || isSaving}
              >
                <Block
                  flexDirection="row"
                  align="center"
                  gap={12}
                  paddings={[16, 12]}
                >
                  <Image
                    source={require("assets/icons/upload-simple-large.png")}
                    width={16}
                    height={16}
                    style={styles.icon}
                    tintColor={Colors.primary}
                  />
                  <Text size={TextSize.small} color={Colors.primary}>
                    Upload
                  </Text>
                </Block>
              </Button.Wrapper>
              <Button.Wrapper
                onPress={handleRemove}
                disabled={isRemoveDisabled()}
              >
                <Block
                  flexDirection="row"
                  align="center"
                  gap={12}
                  paddings={[16, 12]}
                >
                  <Image
                    source={require("assets/icons/trash.png")}
                    width={16}
                    height={16}
                    style={styles.icon}
                  />
                  <Text size={TextSize.small}>Remove</Text>
                </Block>
              </Button.Wrapper>
            </Block>
          )}
        </Block>
        <Block gap={20}>
          <Block gap={8}>
            <Text
              size={TextSize.tiny}
              color={Colors.white50}
              paddings={[0, 16]}
            >
              Display name
            </Text>
            <Input
              placeholder="Display name"
              value={displayName}
              disabled={isDirect || !canEditName}
              onChangeText={(value) => setDisplayName(value)}
            />
          </Block>
          <Block gap={8}>
            <Text
              size={TextSize.tiny}
              color={Colors.white50}
              paddings={[0, 16]}
            >
              Topic
            </Text>
            <Input
              placeholder="Add a topic"
              value={topic}
              disabled={!canEditTopic}
              onChangeText={(value) => setTopic(value)}
            />
          </Block>
        </Block>
      </IpadScreenWrapper>
      <Modal
        visible={isListOpen}
        transparent={true}
        presentationStyle="overFullScreen"
        animationType="fade"
      >
        <Block
          width="100%"
          height="100%"
          justify={isIpad() ? "center" : "flex-end"}
          align="center"
          background={Colors.black70}
          paddings={[40, 20]}
        >
          {isLoading && <Loading />}
          <Block maxWidth={600} width="100%" gap={8}>
            <Block
              width="100%"
              background={Colors.blackMinus3}
              border={{ borderRadius: 14 }}
            >
              <SingleSendItem
                title="Chose photo"
                showSeparator
                onPress={handleChoosePhoto}
              />
              <SingleSendItem
                title="Take a photo"
                showSeparator
                onPress={handleTakePhoto}
              />
            </Block>
            <Block
              width="100%"
              background={Colors.blackMinus3}
              border={{ borderRadius: 14 }}
            >
              <SingleSendItem
                title="Cancel"
                onPress={() => setIsListOpen(false)}
              />
            </Block>
          </Block>
        </Block>
      </Modal>
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  icon: {
    width: 16,
    height: 16,
  },
});
